using System.IO;
using System.Text.Json.Nodes;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media.Imaging;
using Microsoft.Win32;
namespace ArchiveReader;
public partial class TutorWindow:Window
{
 readonly string page;readonly Func<string,JsonObject?,CancellationToken,Task<JsonNode>> worker;
 JsonArray? rect;JsonObject? lesson;CancellationTokenSource? work;bool busy,loading;
 static string T(string s)=>Localizer.Text(s);
 Task<JsonNode> Call(string command,JsonObject? args=null)=>worker(command,args,work?.Token??default);
 public TutorWindow(string page,string model,Func<string,JsonObject?,CancellationToken,Task<JsonNode>> worker)
 {
  this.page=page;this.worker=worker;InitializeComponent();ModelA.Text=string.IsNullOrWhiteSpace(model)?FindModel("german-handwriting/model.mlmodel")??"":model;ModelB.Text=FindModel("polish-metrical-experimental")??"";
  Loaded+=async(_,_)=>await Run(async()=>{Localizer.Apply(this,Localizer.Language);await Refresh();var role=await Call("tutor_role",new(){["id"]=page});Role.SelectedItem=Role.Items.Cast<ComboBoxItem>().FirstOrDefault(i=>i.Tag?.ToString()==role["split"]?.ToString())??Role.Items[0];if(Environment.GetCommandLineArgs().Contains("--smoke-tutor")){var rows=await Call("tutor_lessons",new(){["id"]=page});var first=rows.AsArray().FirstOrDefault(n=>n?["page"]?.ToString()==page);rect=first?["rect"]?.DeepClone().AsArray()??new JsonArray(.1,.1,.7,.1);HumanText.Text=first?["text"]?.ToString()??"Synthetic tutor preview";History.Text=first==null?T("Новий приклад"):(await Call("tutor_history",new(){["lesson"]=first["id"]!.ToString()})).ToJsonString(new(){WriteIndented=true});await Preview();Tabs.IsEnabled=true;for(var i=0;i<Tabs.Items.Count;i++){Tabs.SelectedIndex=i;SmokeCapture.Save(this,"tutor-ui",$"tab-{i}.png");}Close();}});
  Closing+=(_,_)=>work?.Cancel();
 }
 static string? FindModel(string relative){for(var folder=new DirectoryInfo(AppContext.BaseDirectory);folder!=null;folder=folder.Parent){var candidate=Path.Combine(folder.FullName,"models",relative.Replace('/',Path.DirectorySeparatorChar));if(File.Exists(candidate)||Directory.Exists(candidate))return candidate;}return null;}
 async Task Run(Func<Task> action){if(busy)return;busy=true;work=new();Tabs.IsEnabled=false;try{await action();}catch(OperationCanceledException){Status.Text=T("Обробку зупинено. Збережені результати залишилися в бібліотеці.");}catch(Exception ex){Status.Text=T(ex.Message);}finally{Tabs.IsEnabled=true;work.Dispose();work=null;busy=false;}}
 void Stop(object s,RoutedEventArgs e)=>work?.Cancel();
 static BitmapImage Bitmap(string path){var b=new BitmapImage();b.BeginInit();b.CacheOption=BitmapCacheOption.OnLoad;b.UriSource=new Uri(path);b.EndInit();b.Freeze();return b;}
 async Task Refresh()=>Lessons.ItemsSource=(await Call("tutor_lessons",new(){["id"]=page})).AsArray().Select(n=>new GenealogyRow(n!.AsObject(),n["number"]+" · "+(n["verified"]!.GetValue<bool>()?"✓ ":"? ")+n["text"]+(n["stale"]!.GetValue<bool>()?" ⚠":""))).ToList();
 async Task Preview(){if(rect==null)return;var r=await Call("render",new(){["id"]=page,["whole"]=true});var b=Bitmap(r["path"]!.ToString());Scan.Source=new CroppedBitmap(b,new Int32Rect((int)(rect[0]!.GetValue<double>()*b.PixelWidth),(int)(rect[1]!.GetValue<double>()*b.PixelHeight),Math.Max(1,(int)(rect[2]!.GetValue<double>()*b.PixelWidth)),Math.Max(1,(int)(rect[3]!.GetValue<double>()*b.PixelHeight))));}
 async void Pick(object s,RoutedEventArgs e)=>await Run(async()=>{var r=await Call("render",new(){["id"]=page,["whole"]=true});var picker=new RegionPicker(r["path"]!.ToString()){Owner=this};if(picker.ShowDialog()==true){rect=picker.Bounds;lesson=null;HumanText.Clear();Notes.Clear();Readings.Clear();Verified.IsChecked=false;await Preview();}});
 void Choose(object s,RoutedEventArgs e){var isA=((Button)s).Tag.ToString()=="A";var target=isA?ModelA:ModelB;var engine=isA?"kraken":((ComboBoxItem)EngineB.SelectedItem).Tag.ToString();if(engine=="trocr"){var d=new OpenFolderDialog();if(d.ShowDialog()==true)target.Text=d.FolderName;}else{var d=new OpenFileDialog{Filter="Kraken|*.mlmodel;*.safetensors"};if(d.ShowDialog()==true)target.Text=d.FileName;}}
 JsonArray Models(){if(string.IsNullOrWhiteSpace(ModelA.Text)||string.IsNullOrWhiteSpace(ModelB.Text))throw new Exception(T("Виберіть дві локальні моделі."));if(Path.GetFullPath(ModelA.Text).Equals(Path.GetFullPath(ModelB.Text),StringComparison.OrdinalIgnoreCase))throw new Exception(T("Для порівняння виберіть різні моделі."));return new(new JsonObject{["name"]="A",["engine"]="kraken",["path"]=ModelA.Text},new JsonObject{["name"]="B",["engine"]=((ComboBoxItem)EngineB.SelectedItem).Tag.ToString(),["path"]=ModelB.Text});}
 static string ReadReport(JsonNode r){var lines=new List<string>();foreach(var row in r["rows"]!.AsArray()){foreach(var result in row!["results"]!.AsObject())lines.Add(result.Key+": "+(result.Value?["text"]??result.Value?["error"]));var status=row["ensemble"]?["status"]?.ToString();lines.Add(T(status=="agreed_unverified"?"Моделі погодилися; потрібна перевірка людиною.":"Прочитання розходяться або є збій; перевірте оригінал."));}return string.Join("\n",lines);}
 async void Recognize(object s,RoutedEventArgs e)=>await Run(async()=>{if(rect==null)throw new Exception(T("Спочатку виберіть рядок."));var r=await Call("tutor_compare",new(){["id"]=page,["rect"]=rect.DeepClone(),["models"]=Models()});Readings.Text=ReadReport(r);Status.Text=T("Перевірте прочитання моделей за сканом.");});
 void TextChanged(object s,TextChangedEventArgs e){if(!loading&&Verified!=null)Verified.IsChecked=false;}
 async void SaveLesson(object s,RoutedEventArgs e)=>await Run(async()=>{if(rect==null)throw new Exception(T("Спочатку виберіть рядок."));var a=new JsonObject{["id"]=page,["rect"]=rect.DeepClone(),["text"]=HumanText.Text,["notes"]=Notes.Text,["verified"]=Verified.IsChecked==true};if(lesson!=null){a["lesson"]=lesson["id"]!.ToString();a["revision"]=lesson["revision"]!.ToString();}lesson=(await Call("tutor_save",a)).AsObject();await Refresh();Status.Text=T("Приклад збережено. Ваги моделі ще не змінені.");});
 async void SelectLesson(object s,SelectionChangedEventArgs e){if(busy||Lessons.SelectedItem is not GenealogyRow row)return;await Run(async()=>{if(row.Data["page"]!.ToString()!=page){History.Text=T("Відкрийте сторінку цього прикладу в головному вікні.");return;}lesson=row.Data;rect=(JsonArray)lesson["rect"]!.DeepClone();loading=true;HumanText.Text=lesson["text"]!.ToString();Notes.Text=lesson["notes"]?.ToString()??"";Verified.IsChecked=lesson["verified"]!.GetValue<bool>()&&!lesson["stale"]!.GetValue<bool>();loading=false;History.Text=string.Join("\n\n",(await Call("tutor_history",new(){["lesson"]=lesson["id"]!.ToString()})).AsArray().Select(h=>h!["created"]+" · "+T(h["action"]!.ToString()=="human_confirmed"?"Підтверджено людиною":"Чернетка")+"\n"+h["data"]?["after"]?["text"]+"\n"+h["data"]?["after"]?["notes"]));await Preview();Tabs.SelectedIndex=0;});}
 void NewLesson(object s,RoutedEventArgs e){lesson=null;rect=null;HumanText.Clear();Notes.Clear();Readings.Clear();Verified.IsChecked=false;Scan.Source=null;Tabs.SelectedIndex=0;}
 async void SaveRole(object s,RoutedEventArgs e)=>await Run(async()=>{await Call("tutor_role",new(){["id"]=page,["role"]=((ComboBoxItem)Role.SelectedItem).Tag.ToString()});Status.Text=T("Збережено");});
 async void Export(object s,RoutedEventArgs e){var d=new OpenFolderDialog();if(d.ShowDialog()!=true)return;await Run(async()=>{var r=await Call("dataset_explicit",new(){["path"]=d.FolderName});TrainingReport.Text=Localizer.Format("Навчання: {0}; перевірка: {1}; тест: {2}; виключено: {3}.",r["train"],r["validation"],r["test"],r["excluded"])+"\n"+r["path"];});}
 async void Train(object s,RoutedEventArgs e)=>await Run(async()=>{var r=await Call("tutor_train",new(){["model"]=ModelA.Text,["epochs"]=int.Parse(Epochs.Text),["confirmed"]=TrainConfirmed.IsChecked==true});TrainingReport.Text=T("Окрема копія моделі")+":\n"+string.Join("\n",r["models"]!.AsArray().Select(m=>m!.ToString()))+"\n"+r["path"];Status.Text=T("Навчання завершено. Перевірте нову копію на тестових книгах.");});
 async void Heldout(object s,RoutedEventArgs e)=>await Run(async()=>{var r=await Call("heldout_compare",new(){["models"]=Models()});TrainingReport.Text=string.Join("\n",r["models"]!.AsArray().Select(m=>m!["name"]+": CER "+m["micro_cer"]+" · "+T("Рядків")+": "+m["scored_lines"]+" · "+T("Збоїв")+": "+m["failed_lines"]))+"\n"+r["path"];});
}
